    const response = await book(24.5, 25.5, 'Reused slot');
    expect(response.statusCode).toBe(201);
  });

  it('reports which booking caused the conflict', async () => {
    const first = await book(24, 25);
    const response = await book(24.5, 25.5, 'Overlap');
    expect(response.json().error.details.conflictingBookingId).toBe(first.json().id);
  });

  describe('room availability', () => {
    async function availability(query: string) {
      return app.inject({ method: 'GET', url: `/bookings/availability?${query}` });
    }

    it('returns the whole window as free when there are no bookings', async () => {
      const response = await availability(`roomId=${roomId}&from=${inHours(24)}&to=${inHours(26)}`);
      expect(response.statusCode).toBe(200);
      const { data } = response.json();
      expect(data).toHaveLength(1);
      expect(new Date(data[0].startsAt).getTime()).toBe(new Date(inHours(24)).getTime());
      expect(new Date(data[0].endsAt).getTime()).toBe(new Date(inHours(26)).getTime());
    });

    it('excludes an active booking from the free slots', async () => {
      await book(24, 25);
      const response = await availability(`roomId=${roomId}&from=${inHours(23)}&to=${inHours(26)}`);
      const { data } = response.json();
      expect(data).toHaveLength(2);
      expect(new Date(data[0].startsAt).getTime()).toBe(new Date(inHours(23)).getTime());
      expect(new Date(data[0].endsAt).getTime()).toBe(new Date(inHours(24)).getTime());
      expect(new Date(data[1].startsAt).getTime()).toBe(new Date(inHours(25)).getTime());
      expect(new Date(data[1].endsAt).getTime()).toBe(new Date(inHours(26)).getTime());
    });

    it('does not list a cancelled booking as occupying time', async () => {
      const first = await book(24, 25);
      await app.inject({ method: 'POST', url: `/bookings/${first.json().id}/cancel` });
      const response = await availability(`roomId=${roomId}&from=${inHours(24)}&to=${inHours(25)}`);
      expect(response.json().data).toHaveLength(1);
    });

    it('omits gaps shorter than the requested (or default minimum) duration', async () => {
      await book(24, 24.75);
      await book(25, 26);
      const response = await availability(`roomId=${roomId}&from=${inHours(24)}&to=${inHours(26)}`);
      expect(response.json().data).toEqual([]);
    });

    it('honours a custom duration filter', async () => {
      await book(24, 24.75);
      const response = await availability(
        `roomId=${roomId}&from=${inHours(24)}&to=${inHours(25)}&duration=10`,
      );
      const { data } = response.json();
      expect(data).toHaveLength(1);
      expect(new Date(data[0].startsAt).getTime()).toBe(new Date(inHours(24.75)).getTime());
    });

    it('answers 404 when the room does not exist', async () => {
      const response = await availability(`roomId=missing&from=${inHours(1)}&to=${inHours(2)}`);
      expect(response.statusCode).toBe(404);
    });

    it('rejects a window where "to" is not after "from"', async () => {
      const response = await availability(`roomId=${roomId}&from=${inHours(5)}&to=${inHours(5)}`);
      expect(response.statusCode).toBe(400);
    });

    it('rejects a duration outside the allowed booking range', async () => {
      const response = await availability(`roomId=${roomId}&from=${inHours(1)}&to=${inHours(2)}&duration=10000`);
      expect(response.statusCode).toBe(400);
    });
  });
});

